-- VaultProof  schema (PostgreSQL), generated by export_schema.py

CREATE TABLE audit_log (
	id SERIAL NOT NULL, 
	ts VARCHAR(40) NOT NULL, 
	actor_id VARCHAR(36), 
	actor_email VARCHAR(255), 
	action VARCHAR(50) NOT NULL, 
	outcome VARCHAR(10) NOT NULL, 
	document_id VARCHAR(36), 
	detail VARCHAR(500) NOT NULL, 
	ip VARCHAR(64), 
	prev_hash VARCHAR(64) NOT NULL, 
	entry_hash VARCHAR(64) NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_audit_log_document_id ON audit_log (document_id);

CREATE INDEX ix_audit_log_action ON audit_log (action);

CREATE TABLE file_blobs (
	storage_name VARCHAR(64) NOT NULL, 
	data BYTEA NOT NULL, 
	PRIMARY KEY (storage_name)
);

CREATE TABLE users (
	id VARCHAR(36) NOT NULL, 
	email VARCHAR(255) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	role VARCHAR(20) NOT NULL, 
	active BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id)
);

CREATE UNIQUE INDEX ix_users_email ON users (email);

CREATE TABLE documents (
	id VARCHAR(36) NOT NULL, 
	owner_id VARCHAR(36) NOT NULL, 
	original_name VARCHAR(255) NOT NULL, 
	category VARCHAR(50) NOT NULL, 
	content_type VARCHAR(100) NOT NULL, 
	size_bytes INTEGER NOT NULL, 
	sha256 VARCHAR(64) NOT NULL, 
	storage_name VARCHAR(64) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE, 
	deleted_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(owner_id) REFERENCES users (id), 
	UNIQUE (storage_name)
);

CREATE INDEX ix_documents_owner_id ON documents (owner_id);

CREATE TABLE grants (
	id SERIAL NOT NULL, 
	document_id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	permission VARCHAR(10) NOT NULL, 
	granted_by VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE, 
	expires_at TIMESTAMP WITH TIME ZONE, 
	revoked_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_grant_doc_user UNIQUE (document_id, user_id), 
	FOREIGN KEY(document_id) REFERENCES documents (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);

CREATE INDEX ix_grants_user_id ON grants (user_id);

CREATE INDEX ix_grants_document_id ON grants (document_id);

-- Audit log protection

CREATE OR REPLACE FUNCTION audit_log_append_only() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'audit_log is append-only';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS audit_log_no_change ON audit_log;

CREATE TRIGGER audit_log_no_change BEFORE UPDATE OR DELETE ON audit_log
FOR EACH ROW EXECUTE FUNCTION audit_log_append_only();

DROP TRIGGER IF EXISTS audit_log_no_truncate ON audit_log;

CREATE TRIGGER audit_log_no_truncate BEFORE TRUNCATE ON audit_log
FOR EACH STATEMENT EXECUTE FUNCTION audit_log_append_only();
